const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Pacific Palisades location and offset regions
  const palisades_lon = -118.53;
  const palisades_lat = 34.05;

  // 50 km west (approximately 0.45 degrees at this latitude)
  const west_lon = palisades_lon - 0.45;
  const west_lat = palisades_lat;
  const west_point = ee.Geometry.Point([west_lon, west_lat]).buffer(5000);

  // 50 km southwest (approximately 0.32 degrees each)
  const sw_lon = palisades_lon - 0.32;
  const sw_lat = palisades_lat - 0.32;
  const sw_point = ee.Geometry.Point([sw_lon, sw_lat]).buffer(5000);

  // 2. Get Sentinel-5P NO2 data for January 7, 2025
  const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate('2025-01-07', '2025-01-08')
    .filterBounds(west_point.union(sw_point));

  const size = await collection.size().getInfo();
  console.log(`Total images found: ${size}`);

  if (size === 0) {
    console.log('No Sentinel-5P data available for this date.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Process NO2 data with quality filtering
  const no2_band = 'tropospheric_NO2_column_number_density';
  const qa_band = 'qa_value';

  function maskQuality(image) {
    const qa = image.select(qa_band);
    const mask = qa.gte(0.75);
    return image.select(no2_band).updateMask(mask);
  }

  const no2_image = collection.map(maskQuality).mean();

  // 4. Calculate NO2 for west region
  const west_result = await no2_image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: west_point,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const west_count = await no2_image.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: west_point,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  // 5. Calculate NO2 for southwest region
  const sw_result = await no2_image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: sw_point,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const sw_count = await no2_image.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: sw_point,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const west_no2 = west_result[no2_band];
  const west_pixels = west_count[no2_band];
  const sw_no2 = sw_result[no2_band];
  const sw_pixels = sw_count[no2_band];

  console.log(`West region - NO2: ${west_no2}, Valid pixels: ${west_pixels}`);
  console.log(`Southwest region - NO2: ${sw_no2}, Valid pixels: ${sw_pixels}`);

  // 6. Validation and answer
  if (west_pixels === 0 || sw_pixels === 0) {
    console.log('No valid pixels after quality masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (west_no2 == null || sw_no2 == null || isNaN(west_no2) || isNaN(sw_no2)) {
    console.log('Invalid NO2 calculation results.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare NO2 concentrations
  if (west_no2 > sw_no2) {
    console.log(`West NO2 (${west_no2.toExponential(3)}) > SW NO2 (${sw_no2.toExponential(3)})`);
    console.log('<answer>A</answer>');
  } else {
    console.log(`West NO2 (${west_no2.toExponential(3)}) <= SW NO2 (${sw_no2.toExponential(3)})`);
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
